//! Fixtures generated by pinned original Cell Pattern dispatch.
use filmcraft_project::{Param,ParamValue};
use filmcraft_render::{effects::{apply,FxCtx},image::Image};
use serde_json::json;
fn main(){let mut cases=vec![];
for(w,h)in[(1,7),(7,1),(6,4),(18,10)] {for pattern in 0u32..8 {for overflow in 0u32..3 {for invert in [false,true] {for(contrast,disperse,size,evolution,seed)in[(0.,0.,0.,0.,0.),(100.,1.,2.5,90.,2.5),(10000.,1.5,2000.,-1234.,10000.)] {for offset in [[None,None],[Some(-1.23456789012345),Some(2.125)]] {
let rgba:Vec<u8>=(0..w*h).flat_map(|i|[[64,128,192,128],[0,0,0,0],[0,255,0,255]][i%3]).collect();
let px=rgba.chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;[filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[1]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[2]as f32/255.)*a,a]}).collect();let mut image=Image{w,h,px};
let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="cell_pattern").unwrap().instance();
for(name,v)in[("contrast",contrast),("disperse",disperse),("size",size),("evolution",evolution),("seed",seed)]{effect.params.insert(name.into(),Param::new(ParamValue::Float(v)));}
effect.params.insert("pattern".into(),Param::new(ParamValue::Choice(pattern)));effect.params.insert("overflow".into(),Param::new(ParamValue::Choice(overflow)));effect.params.insert("invert".into(),Param::new(ParamValue::Bool(invert)));effect.params.insert("offset".into(),Param::new(ParamValue::Vec2(filmcraft_geom::Vec2::new(offset[0].unwrap_or(f64::NAN),offset[1].unwrap_or(f64::NAN)))));
let cx=FxCtx{t:filmcraft_time::Tick(0),px_scale:1.,seconds:0.,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut image,&effect,&cx);
cases.push(json!({"parameters":{"pattern":pattern,"overflow":overflow,"invert":invert,"offset":offset,"contrast":contrast,"disperse":disperse,"size":size,"evolution":evolution,"seed":seed},"width":w,"height":h,"rgba":rgba,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));
}}}}}}
 let mut media=vec![];
 for pattern in 0u32..8 {for overflow in 0u32..3 {for invert in [false,true] {for tick in [0u64,250000,500000] {
  let rgba:Vec<u8>=(0..256).flat_map(|i|{let v=if i%16<8&&i/16<12 {255}else{32};[v,v,v,if i%16<8&&i/16<12 {128}else{0}]}).collect();
  let mut frames=vec![];
  for index in 0..(1000000-tick).div_ceil(100000) {
   let local=(tick+index*100000).min(500000);let progress=local as f64/500000.0;
   let px:Vec<f32>=rgba.chunks_exact(4).flat_map(|p|{let a=p[3] as f32/255.0;let v=filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a;[v,v,v,a]}).collect();
   let mut image=Image{w:16,h:16,px};
   let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="cell_pattern").unwrap().instance();
   effect.params.insert("offset".into(),Param::new(ParamValue::Vec2(filmcraft_geom::Vec2::new(-1.25+progress*3.375,0.5-progress*1.0))));
   for(name,value)in [("contrast",100.0+progress*300.0),("disperse",progress*1.5),("size",1.0+progress*5.5),("evolution",progress*180.0),("seed",progress*3.5)]{effect.params.insert(name.into(),Param::new(ParamValue::Float(value)));}
   effect.params.insert("pattern".into(),Param::new(ParamValue::Choice(pattern)));
   effect.params.insert("overflow".into(),Param::new(ParamValue::Choice(overflow)));
   effect.params.insert("invert".into(),Param::new(ParamValue::Bool(invert)));
   let cx=FxCtx{t:filmcraft_time::Tick(local as i64),px_scale:1.0,seconds:local as f64/1000000.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
   apply(&mut image,&effect,&cx);frames.push(image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>());
  }
  media.push(json!({"pattern":pattern,"overflow":overflow,"invert":invert,"localTick":tick,"rgba":rgba,"bits":frames[0],"frames":frames}));
 }
 }
 }
 }
println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"media":media}));}
